const rtdal001202Source0003 = `idesc_get_remotes <- function(self, private) {
  remotes <- self$get("Remotes")
  if (is.na(remotes)) {
    character()
  } else {
    parse_remotes(remotes)
  }
}`

const rtdal001202Source0004 = `idesc_set_remotes <- function(self, private, remotes) {
  stopifnot(is.character(remotes))
  self$set(Remotes = deparse_remotes(remotes))
  invisible(self)
}`

const rtdal001202Source0005 = `idesc_add_remotes <- function(self, private, remotes) {
  stopifnot(is.character(remotes))
  remotes <- unique(c(self$get_remotes(), remotes))
  self$set(Remotes = deparse_remotes(remotes))
  invisible(self)
}`

const rtdal001202Source0006 = `idesc_del_remotes <- function(self, private, pattern) {
  stopifnot(is_string(pattern))
  remotes <- self$get_remotes()
  if (length(remotes) == 0) return(invisible(self))

  filt <- grep(pattern, remotes, invert = TRUE, value = TRUE, perl = TRUE)
  if (length(filt) > 0) {
    self$set(Remotes = deparse_remotes(filt))
  } else {
    self$del("Remotes")
  }
  invisible(self)
}`

const rtdal001202Source0007 = `idesc_clear_remotes <- function(self, private) {
  self$del("Remotes")
  invisible(self)
}`

