const rtdal001206Source0005 = "RFC_2822_email_regexp <- (function() {\n\n  ## Local part consists of ASCII letters and digits, the characters\n  ##   ! # $ % * / ? | ^ { } ` ~ & ' + = _ -\n  ## and . provided it is not leading or trailing or repeated, or must\n  ## be a quoted string.\n  ## Domain part consists of dot-separated elements consisting of\n  ## ASCII letters, digits and hyphen.\n  ## We could also check that the local and domain parts are no longer\n  ## than 64 and 255 characters, respectively.\n  ## See http://en.wikipedia.org/wiki/Email_address.\n\n  ASCII_letters_and_digits <-\n    \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789\"\n  l <- sprintf(\"[%s%s]\", ASCII_letters_and_digits, \"!#$%*/?|^{}`~&'+=_-\")\n  d <- sprintf(\"[%s%s]\", ASCII_letters_and_digits, \"-\")\n  ## Be careful to arrange the hyphens to come last in the range spec.\n  sprintf(\"(\\\\\\\".+\\\\\\\"|(%s+\\\\.)*%s+)@(%s+\\\\.)*%s+\", l, l, d, d)\n})()"

const rtdal001206Source0011 = `ngrepl <- function(pattern, x, ...) {
  if (is.null(pattern)) pattern <- ""
  x <- flatten(x)
  grepl(pattern, x, ...)
}`

const rtdal001206Source0018 = `fixed_deparse1 <- function(x, ...) {
  x <- unicode_encode(x)
  out <- paste(deparse(x, width.cutoff = 500L, ...), collapse = " ")
  out <- unicode_decode(out)
  out
}`

const rtdal001206Source0019 = `unicode_encode <- function(x) {
  x[] <- vapply(x, unicode_encode1, character(1), USE.NAMES = FALSE)
  x
}`

const rtdal001206Source0021 = `unicode_decode <- function(x) {
  mch <- gregexpr("<U\\+([0-9a-fA-F]+)>", x, perl = TRUE)
  uni <- regmatches(x, mch)
  rep <- lapply(uni, parse_escaped_unicode)
  regmatches(x, mch) <- rep
  x <- enc2utf8(x)
  Encoding(x) <- "UTF-8"
  x
}`

const rtdal001206Source0024 = `desc_message <- function(...) {
  msg <- simpleMessage(paste0(..., "\n"), sys.call())
  class(msg) <- c("descMessage", class(msg))
  message(msg)

}`

const rtdal001206Source0025 = `write_dcf <- function(...) {
  if (getRversion() >= "3.5.0") {
    write.dcf(..., useBytes = TRUE)
  } else {
    write.dcf(...)
  }
}`

