const rtdal001222Source0001 = `test_that("dependencies are not reformatted if new value is the same", {

  desc <- description$new(test_path("D1"))
  desc$set("Imports", "R6")
  before <- desc$get("Imports")
  desc$set_dep("R6")
  after <- desc$get("Imports")
  expect_equal(before, after)
  
  desc <- description$new(test_path("D1"))
  desc$set("Imports", "R6")
  before <- desc$get("Imports")
  desc$set_deps(data.frame(package = "R6", type = "Imports", version = "*"))
  after <- desc$get("Imports")
  expect_equal(before, after)
})`

const rtdal001222Source0002 = `test_that("collate fields are not reformatted if new value is the same", {

  desc <- description$new(test_path("D1"))
  desc$set("Collate", "'foo.R' 'bar.R' foobar.R")
  before <- desc$get("Collate")
  desc$set_collate(desc$get_collate())
  after <- desc$get("Collate")
  expect_equal(before, after)
})`

